**`src/campaigns/analytics.ts` — `generateCampaignReport`**

`campaign.posts` is iterated once per platform inside `analyzePlatform`, then filtered *again* to compute `totalClicks`. With 4 platforms and 1,000 posts, that's 5 full passes.

```typescript
// BEFORE — O(platforms × posts) + extra filter pass
const platforms = campaign.platforms.map(p =>
  analyzePlatform(campaign.posts, p, period)  // scans all posts each time
);
const totalClicks = sum(
  campaign.posts.filter(p => p.analytics),    // another scan
  p => p.analytics!.clicks
);

// AFTER — group once, then distribute
function generateCampaignReport(campaign: SocialCampaign): CampaignReport {
  const period = { start: campaign.startDate, end: campaign.endDate };

  // Single pass: bucket posts by platform, accumulate clicks
  const byPlatform = new Map<SocialPlatform, SocialPost[]>();
  let totalClicks = 0;
  for (const post of campaign.posts) {
    if (!post.analytics) continue;
    totalClicks += post.analytics.clicks;
    const bucket = byPlatform.get(post.platform) ?? [];
    bucket.push(post);
    byPlatform.set(post.platform, bucket);
  }

  const platforms = campaign.platforms.map(p =>
    analyzePlatformFromBucket(byPlatform.get(p) ?? [], p, period)
  );
  // ... rest unchanged
}
```

**`src/agents/tier1/memory-agent.ts` — `VectorStore.searchByType`**

Full table scan with no secondary index on `type`. Every search iterates all entries.

```typescript
// BEFORE — O(n) full scan
async searchByType(type: MemoryEntry['type'], limit = 100): Promise<MemoryEntry[]> {
  const results: MemoryEntry[] = [];
  for (const entry of this.entries) { /* ... */ }
}

// AFTER — maintain a type index
class VectorStore {
  private entries: Map<string, MemoryEntry>;
  private embeddings: Map<string, number[]>;
  private typeIndex: Map<MemoryEntry['type'], Set<string>> = new Map(); // NEW

  async store(entry: MemoryEntry): Promise<void> {
    this.entries.set(entry.id, entry);
    if (entry.embedding) this.embeddings.set(entry.id, entry.embedding);
    // Index by type
    const bucket = this.typeIndex.get(entry.type) ?? new Set();
    bucket.add(entry.id);
    this.typeIndex.set(entry.type, bucket);
  }

  async delete(id: string): Promise<void> {
    const entry = this.entries.get(id);
    if (entry) this.typeIndex.get(entry.type)?.delete(id);
    this.entries.delete(id);
    this.embeddings.delete(id);
  }

  async searchByType(type: MemoryEntry['type'], limit = 100): Promise<MemoryEntry[]> {
    const ids = this.typeIndex.get(type);
    if (!ids) return [];
    const results: MemoryEntry[] = [];
    for (const id of ids) {
      if (results.length >= limit) break;
      const entry = this.entries.get(id);
      if (entry) results.push(entry);
    }
    return results;
  }
}
```

