**`src/agents/tier2/simulation-agent.ts` — Unbounded simulation result cache**

The simulation cache is a plain `Map` with no eviction policy. Long-running processes accumulate stale results indefinitely; it's only cleared on shutdown.

```typescript
// BEFORE
private simulationCache: Map<string, SimulationResult[]> = new Map();

// AFTER — use the existing LRUCache from src/performance/cache.ts
import { LRUCache } from '../../performance/cache.js';

private simulationCache = new LRUCache<SimulationResult[]>({
  maxSize: 500,
  ttlMs: 30 * 60 * 1000, // 30 minutes — simulations go stale
});
```

**`src/campaigns/hashtag-analyzer.ts` — Recomputing static scores on every call**

`recommendHashtags` scores all hashtags in `HASHTAG_DB` on every invocation. Since `HASHTAG_DB` is a module-level constant, these scores can be pre-computed once per `(niche, platform)` pair.

```typescript
// BEFORE — recomputes O(|HASHTAG_DB|) scores every call
export function recommendHashtags(platform, niche, campaignTag?, maxTotal?) {
  const scored = Object.keys(HASHTAG_DB)
    .map(tag => scoreHashtag(tag, niche, platform))
    .sort((a, b) => b.score - a.score);
  // ...
}

// AFTER — memoize at module level
const _scoredCache = new Map<string, HashtagScore[]>();

function getScoredHashtags(niche: string, platform: SocialPlatform): HashtagScore[] {
  const key = `${niche}:${platform}`;
  if (_scoredCache.has(key)) return _scoredCache.get(key)!;

  const scored = Object.keys(HASHTAG_DB)
    .map(tag => scoreHashtag(tag, niche, platform))
    .sort((a, b) => b.score - a.score);
  _scoredCache.set(key, scored);
  return scored;
}

export function recommendHashtags(platform, niche, campaignTag?, maxTotal?) {
  const scored = getScoredHashtags(niche, platform);
  // ... rest unchanged
}
```

**`src/agents/tier4/causal-graph-builder-agent.ts` — BFS path results not memoized**

`findPaths(source, target, maxDepth)` re-runs BFS every call. For attribution analysis, the same source→target pairs are queried repeatedly.

```typescript
class GraphEngine {
  private pathCache = new Map<string, CausalPath[]>();

  findPaths(source: string, target: string, maxDepth = 5): CausalPath[] {
    const cacheKey = `${source}→${target}:${maxDepth}`;
    if (this.pathCache.has(cacheKey)) return this.pathCache.get(cacheKey)!;

    const paths = this._computePaths(source, target, maxDepth);
    this.pathCache.set(cacheKey, paths);
    return paths;
  }

  // Call invalidatePaths() when edges/nodes are added
  invalidatePaths(): void {
    this.pathCache.clear();
  }
}
```

